\set ON_ERROR_STOP on
BEGIN;
DO $$ BEGIN IF current_setting('maiprop.test_disposable_database',true) IS DISTINCT FROM current_database() OR inet_server_addr() IS NOT NULL OR current_database() IN ('postgres','template0','template1','maiprop_replay_current_20260921') THEN RAISE EXCEPTION 'Explicit matching disposable socket database required'; END IF; END $$;
SET LOCAL statement_timeout='30s';
CREATE EXTENSION IF NOT EXISTS pgtap;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
-- Privileged synthetic identity/entitlement setup only; actual application mutations below run normal triggers.
SET LOCAL session_replication_role=replica;
INSERT INTO auth.users(id,email) VALUES ('7b010000-0000-4000-8000-000000000001','t7b-owner@example.test'),('7b010000-0000-4000-8000-000000000002','t7b-manager@example.test'),('7b010000-0000-4000-8000-000000000003','t7b-viewer@example.test'),('7b010000-0000-4000-8000-000000000004','t7b-outsider@example.test'),('7b010000-0000-4000-8000-000000000005','t7b-admin@example.test');
INSERT INTO public.profiles(user_id,role,force_pro_access,display_name) SELECT id,CASE WHEN id::text LIKE '%0005' THEN 'admin'::public.user_role ELSE 'developer'::public.user_role END,true,'Synthetic Task7b' FROM auth.users WHERE id::text LIKE '7b010000%';
INSERT INTO public.organizations(id,name,slug,created_by,plan) VALUES ('7b030000-0000-4000-8000-000000000001','Task7b Org','t7b-org','7b010000-0000-4000-8000-000000000001','pro');
INSERT INTO public.organization_memberships(organization_id,user_id,role,status) VALUES ('7b030000-0000-4000-8000-000000000001','7b010000-0000-4000-8000-000000000001','owner','active'),('7b030000-0000-4000-8000-000000000001','7b010000-0000-4000-8000-000000000002','member','active'),('7b030000-0000-4000-8000-000000000001','7b010000-0000-4000-8000-000000000003','viewer','active');
SET LOCAL session_replication_role=origin;
SET LOCAL app.settings.supabase_url='https://task7b.example.test';
-- Helpers are invoker-only test conveniences, not application authorization replacements.
CREATE FUNCTION pg_temp.object_path(p uuid, filename text) RETURNS text LANGUAGE sql AS $$ SELECT '7b010000-0000-4000-8000-000000000001/'||p::text||'/create/'||filename $$;
CREATE FUNCTION pg_temp.object_url(p uuid, filename text) RETURNS text LANGUAGE sql AS $$ SELECT 'https://task7b.example.test/storage/v1/object/public/listing-images/'||pg_temp.object_path(p,filename) $$;
CREATE FUNCTION pg_temp.create_graph(p uuid, org uuid DEFAULT NULL) RETURNS jsonb LANGUAGE sql AS $$ SELECT public.create_new_building_listing_with_storage_for_service('7b010000-0000-4000-8000-000000000001',org,'new_build',jsonb_build_object('id',p,'name','Task7b Graph','city','Athens','building_permit_number','TEST'), '[{"price":200000,"internal_sqm":80,"unit_id":"A1"}]','[]',jsonb_build_object('title','Task7b Listing','cover_image_url',pg_temp.object_url(p,'cover.jpg')),'[]',jsonb_build_array(jsonb_build_object('bucket','listing-images','object_path',pg_temp.object_path(p,'cover.jpg')))) $$;
SELECT ok(NOT (SELECT cleanup_enabled FROM private.storage_cleanup_rollout_control),'gate defaults closed');
SELECT ok(NOT has_table_privilege('service_role','private.storage_cleanup_rollout_control','SELECT'),'service cannot read rollout control');
SELECT ok(NOT has_table_privilege('authenticated','public.storage_cleanup_jobs','UPDATE'),'browser cannot rewrite jobs');
SET LOCAL ROLE anon;
SELECT throws_ok($q$SELECT public.register_new_building_storage_upload(NULL,NULL,NULL,NULL)$q$,'42501',NULL,'anonymous registration denied by real role');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','',true),set_config('request.jwt.claims','{"role":"authenticated","sub":"7b010000-0000-4000-8000-000000000001"}',true);
SELECT throws_ok($q$SELECT public.claim_storage_cleanup_jobs()$q$,'42501',NULL,'browser cannot claim');
SELECT throws_ok($q$SELECT public.invoke_storage_cleanup_cron()$q$,'42501',NULL,'browser cannot invoke');
SELECT lives_ok($q$SELECT public.register_new_building_storage_upload('7b020000-0000-4000-8000-000000000001','listing-images',pg_temp.object_path('7b020000-0000-4000-8000-000000000001','cover.jpg'),pg_temp.object_url('7b020000-0000-4000-8000-000000000001','cover.jpg'))$q$,'registration remains usable while closed');
RESET ROLE;
SELECT is((SELECT status FROM public.storage_cleanup_jobs WHERE project_id='7b020000-0000-4000-8000-000000000001'),'pending','registration creates pending job');
CREATE TEMP TABLE gate_before AS SELECT * FROM public.storage_cleanup_jobs;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true),set_config('request.jwt.claim.role','service_role',true);
SELECT is((SELECT count(*) FROM public.claim_storage_cleanup_jobs()),0::bigint,'closed claim returns zero');
SELECT is(public.prepare_storage_cleanup_delete('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002'),'lost','closed prepare never authorizes delete');
SELECT is(public.invoke_storage_cleanup_cron(),NULL::bigint,'closed invoker returns null before managed calls');
SELECT lives_ok($q$SELECT pg_temp.create_graph('7b020000-0000-4000-8000-000000000001')$q$,'strict graph creation with normal triggers');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.projects WHERE id='7b020000-0000-4000-8000-000000000001'),1::bigint,'one project committed');
SELECT is((SELECT count(*) FROM public.project_units WHERE project_id='7b020000-0000-4000-8000-000000000001'),1::bigint,'one unit committed');
SELECT is((SELECT status FROM public.storage_cleanup_jobs WHERE project_id='7b020000-0000-4000-8000-000000000001'),'completed','registered graph settles job');
SET LOCAL ROLE service_role;
SELECT lives_ok($q$SELECT pg_temp.create_graph('7b020000-0000-4000-8000-000000000001')$q$,'lost commit response retry succeeds');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.listings WHERE project_id='7b020000-0000-4000-8000-000000000001'),1::bigint,'retry has one representative listing');


-- Disabled calls preserve every queue field, not just row count.
SELECT is((SELECT attempts FROM public.storage_cleanup_jobs WHERE project_id='7b020000-0000-4000-8000-000000000001'),0,'disabled calls do not increment attempts');
DELETE FROM private.storage_cleanup_rollout_control;
SET LOCAL ROLE service_role;
SELECT is((SELECT count(*) FROM public.claim_storage_cleanup_jobs()),0::bigint,'missing control row disables claim');
SELECT is(public.prepare_storage_cleanup_delete(gen_random_uuid(),gen_random_uuid()),'lost','missing control row disables prepare');
SELECT is(public.invoke_storage_cleanup_cron(),NULL::bigint,'missing control row disables invocation');
RESET ROLE;
INSERT INTO private.storage_cleanup_rollout_control VALUES(true,false);
CREATE FUNCTION pg_temp.manifest(p uuid, filename text DEFAULT 'cover.jpg') RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_build_array(jsonb_build_object('bucket','listing-images','object_path',pg_temp.object_path(p,filename),'object_url',pg_temp.object_url(p,filename))) $$;
-- Failure injection is AFTER each real graph stage, retaining all normal trigger effects.
CREATE FUNCTION pg_temp.inject_graph_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF current_setting('maiprop.test_fail_graph_stage',true)=TG_TABLE_NAME THEN RAISE EXCEPTION 'synthetic_graph_failure'; END IF; RETURN NEW; END $$;
CREATE TRIGGER task7b_inject AFTER INSERT ON public.projects FOR EACH ROW EXECUTE FUNCTION pg_temp.inject_graph_failure();
CREATE TRIGGER task7b_inject AFTER INSERT ON public.project_units FOR EACH ROW EXECUTE FUNCTION pg_temp.inject_graph_failure();
CREATE TRIGGER task7b_inject AFTER INSERT ON public.listings FOR EACH ROW EXECUTE FUNCTION pg_temp.inject_graph_failure();
CREATE TRIGGER task7b_inject AFTER INSERT ON public.project_media FOR EACH ROW EXECUTE FUNCTION pg_temp.inject_graph_failure();
CREATE TRIGGER task7b_inject AFTER INSERT ON public.listing_images FOR EACH ROW EXECUTE FUNCTION pg_temp.inject_graph_failure();
