SELECT public.register_new_building_storage_upload('7b020000-0000-4000-8000-000000000002','listing-images',pg_temp.object_path('7b020000-0000-4000-8000-000000000002','cover.jpg'),pg_temp.object_url('7b020000-0000-4000-8000-000000000002','cover.jpg'));
