CREATE FUNCTION pg_temp.attach_manager() RETURNS jsonb LANGUAGE sql AS $$ SELECT public.attach_project_media_for_service('7b010000-0000-4000-8000-000000000002','7b020000-0000-4000-8000-000000000002','{"url":"https://task7b.example.test/storage/v1/object/public/project-media/7b010000-0000-4000-8000-000000000002/7b020000-0000-4000-8000-000000000002/media/render.jpg","media_type":"rendering"}') $$;
UPDATE public.storage_cleanup_jobs SET status='held' WHERE reason='synthetic_upload'; SET LOCAL ROLE service_role;
