SELECT is(public.prepare_storage_cleanup_delete('7b040000-0000-4000-8000-000000000001',gen_random_uuid()),'lost','wrong token lost');
SELECT is(public.prepare_storage_cleanup_delete('7b040000-0000-4000-8000-000000000001',(SELECT lease_token FROM public.storage_cleanup_jobs WHERE id='7b040000-0000-4000-8000-000000000001')),'delete','isolated unreferenced prepare authorizes exact lease');
SELECT throws_ok($q$SELECT public.attach_project_media_for_service('7b010000-0000-4000-8000-000000000001','7b020000-0000-4000-8000-000000000002','{"url":"https://task7b.example.test/storage/v1/object/public/project-media/7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/lease.jpg","media_type":"rendering"}')$q$,'55000','storage_cleanup_in_progress','attachment after prepare is excluded while lease processing');
RESET ROLE;
CREATE TEMP TABLE old_lease AS SELECT id,lease_token FROM public.storage_cleanup_jobs WHERE id='7b040000-0000-4000-8000-000000000001';
GRANT SELECT ON old_lease TO service_role;
UPDATE public.storage_cleanup_jobs SET lease_expires_at=now()-interval '1 minute' WHERE id='7b040000-0000-4000-8000-000000000001';
SET LOCAL ROLE service_role;
SELECT is((SELECT count(*) FROM public.claim_storage_cleanup_jobs(1)),1::bigint,'expired lease can be reclaimed');
SELECT is(public.prepare_storage_cleanup_delete('7b040000-0000-4000-8000-000000000001',(SELECT lease_token FROM old_lease)),'lost','old token cannot prepare after reclaim');
WITH changed AS (UPDATE public.storage_cleanup_jobs SET status='completed' WHERE id='7b040000-0000-4000-8000-000000000001' AND status='processing' AND lease_token=(SELECT lease_token FROM old_lease) RETURNING id) SELECT is((SELECT count(*) FROM changed),0::bigint,'stale worker settlement cannot overwrite successor');
RESET ROLE;
UPDATE private.storage_cleanup_rollout_control SET cleanup_enabled=false;
CREATE TEMP TABLE closed_processing AS SELECT * FROM public.storage_cleanup_jobs WHERE id='7b040000-0000-4000-8000-000000000001';
SET LOCAL ROLE service_role;
SELECT is(public.prepare_storage_cleanup_delete('7b040000-0000-4000-8000-000000000001',(SELECT lease_token FROM public.storage_cleanup_jobs WHERE id='7b040000-0000-4000-8000-000000000001')),'lost','closing gate stops preexisting processing lease');
RESET ROLE;
SELECT is((SELECT to_jsonb(j) FROM public.storage_cleanup_jobs j WHERE id='7b040000-0000-4000-8000-000000000001'),(SELECT to_jsonb(j) FROM closed_processing j),'disabled prepare leaves all processing fields unchanged');
-- Preserve explicit registration semantics separately from strict attachment ticket checks.
UPDATE public.storage_cleanup_jobs SET status='held' WHERE id='7b040000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"7b010000-0000-4000-8000-000000000001"}',true);
SELECT throws_ok($q$SELECT public.register_new_building_storage_upload('7b020000-0000-4000-8000-000000000002','project-media','7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/lease.jpg','https://task7b.example.test/storage/v1/object/public/project-media/7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/lease.jpg')$q$,'55000','storage_cleanup_in_progress','explicit registration held contract'); RESET ROLE;
UPDATE public.storage_cleanup_jobs SET status='processing' WHERE id='7b040000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"7b010000-0000-4000-8000-000000000001"}',true);
SELECT throws_ok($q$SELECT public.register_new_building_storage_upload('7b020000-0000-4000-8000-000000000002','project-media','7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/lease.jpg','https://task7b.example.test/storage/v1/object/public/project-media/7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/lease.jpg')$q$,'55000','storage_cleanup_in_progress','explicit registration processing contract'); RESET ROLE;
UPDATE public.storage_cleanup_jobs SET status='completed' WHERE id='7b040000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"7b010000-0000-4000-8000-000000000001"}',true);
SELECT lives_ok($q$SELECT public.register_new_building_storage_upload('7b020000-0000-4000-8000-000000000002','project-media','7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/lease.jpg','https://task7b.example.test/storage/v1/object/public/project-media/7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/lease.jpg')$q$,'explicit registration completed contract'); RESET ROLE;
UPDATE public.storage_cleanup_jobs SET status='dead' WHERE id='7b040000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"7b010000-0000-4000-8000-000000000001"}',true);
SELECT lives_ok($q$SELECT public.register_new_building_storage_upload('7b020000-0000-4000-8000-000000000002','project-media','7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/lease.jpg','https://task7b.example.test/storage/v1/object/public/project-media/7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/lease.jpg')$q$,'explicit registration dead contract'); RESET ROLE;
SELECT is((SELECT status FROM public.storage_cleanup_jobs WHERE id='7b040000-0000-4000-8000-000000000001'),'pending','explicit completed/dead registration resets to pending; never an automatic attachment fallback');
SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"7b010000-0000-4000-8000-000000000004"}',true);
SELECT throws_ok($q$SELECT public.register_new_building_storage_upload('7b020000-0000-4000-8000-000000000002','project-media','7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/lease.jpg','https://task7b.example.test/storage/v1/object/public/project-media/7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/lease.jpg')$q$,'22023','storage_upload_path_invalid','foreign actor cannot re-register another owner path');
RESET ROLE;
SELECT ok(NOT (SELECT cleanup_enabled FROM private.storage_cleanup_rollout_control),'lease diagnostic returns gate to closed before rollback');


SELECT set_config('maiprop.test_listing_id',(SELECT id::text FROM public.listings WHERE project_id='7b020000-0000-4000-8000-000000000002'),true);
-- Boundary mismatches never create an upload registration.
SET LOCAL ROLE authenticated; SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"7b010000-0000-4000-8000-000000000001"}',true);
SELECT throws_ok($q$SELECT public.register_new_building_storage_upload('7b020000-0000-4000-8000-000000000002','listing-images',pg_temp.object_path('7b020000-0000-4000-8000-000000000002','bad.jpg'),'https://foreign.example.test/storage/v1/object/public/listing-images/'||pg_temp.object_path('7b020000-0000-4000-8000-000000000002','bad.jpg'))$q$,'22023','storage_upload_url_invalid','wrong origin rejected');
SELECT throws_ok($q$SELECT public.register_new_building_storage_upload('7b020000-0000-4000-8000-000000000002','listing-images',pg_temp.object_path('7b020000-0000-4000-8000-000000000002','../bad.jpg'),pg_temp.object_url('7b020000-0000-4000-8000-000000000002','../bad.jpg'))$q$,'22023','storage_upload_path_invalid','traversal rejected');
SELECT throws_ok($q$SELECT public.register_new_building_storage_upload('7b020000-0000-4000-8000-000000000002','other-bucket',pg_temp.object_path('7b020000-0000-4000-8000-000000000002','bad.jpg'),pg_temp.object_url('7b020000-0000-4000-8000-000000000002','bad.jpg'))$q$,'22023','storage_upload_path_invalid','wrong bucket rejected');
RESET ROLE;
SET LOCAL ROLE service_role; SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT throws_ok($q$SELECT public.update_listing_cover_with_storage_for_service('7b010000-0000-4000-8000-000000000001','7b020000-0000-4000-8000-000000000002',current_setting('maiprop.test_listing_id')::uuid,pg_temp.object_url('7b020000-0000-4000-8000-000000000002','cover.jpg'))$q$,'55000','storage_cleanup_in_progress','committed cover reuse receives clear strict rejection');
RESET ROLE;
-- Current reference-predicate gap is an explicit activation blocker, not a passing deletion-safety claim.
UPDATE public.projects SET cover_image_url='https://task7b.example.test/storage/v1/object/public/project-media/7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/project-cover.jpg' WHERE id='7b020000-0000-4000-8000-000000000002';
SET LOCAL ROLE service_role;
SELECT is(public.is_storage_object_committed('project-media','7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/project-cover.jpg','https://task7b.example.test/storage/v1/object/public/project-media/7b010000-0000-4000-8000-000000000001/7b020000-0000-4000-8000-000000000002/media/project-cover.jpg'),false,'known project-cover predicate gap reproduced: activation remains blocked');
RESET ROLE;

SELECT * FROM finish();
ROLLBACK;
